        public VerificationInfoListPagedModel GetCandidateAddressListForTLAllocationByMgr(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                //IQueryable<PQAddress> data = db.PQAddresss.Include("PQPersonal").Include("PQClientMaster").Where(p => p.MgrAllocatedTo == teamMemerRowId);
                IQueryable<PQAddressStatus> data = db.PQAddressStatus.Include("PQAddress").Where(p => p.MgrAllocatedTo == teamMemerRowId && p.TLAllocatedTo == 0);

                if (!string.IsNullOrEmpty(CheckStatus))
                {
                    data = data.Where(p => p.MgrCheckStatus == CheckStatus);
                }

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQAddress.ClientRowID == ClientRowID);
                }

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQAddress.PQPersonal.Name + " " + b.PQAddress.PQPersonal.MiddleName + " " + b.PQAddress.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQAddress.PQPersonal.ClientRefID == Search || b.PQAddress.AV_Sec_Ref_No == Search || b.PQAddress.CheckStatus == Search || b.PQAddress.UniqueComponentID == Search || b.PQAddress.PQPersonal.CandidateCode == Search);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQAddress.PersonalRowID) : data.OrderByDescending(d => d.PQAddress.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.PQAddress.AddressRowID,
                    ClientRowID = item.PQAddress.ClientRowID,
                    ClientName = item.PQAddress.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQAddress.PersonalRowID,
                    PersonalName = item.PQAddress.PQPersonal.Name + " " + item.PQAddress.PQPersonal.MiddleName + " " + item.PQAddress.PQPersonal.LastName,
                    CandidateCode = item.PQAddress.PQPersonal.CandidateCode,//copy
                    InternalOutDate = item.PQAddress.InternalOutDate,
                    ClientRefID = item.PQAddress.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQAddress.AV_Sec_Ref_No,
                    OutDate = item.PQAddress.OutDate,//to
                    ClientPackageRowID = item.PQAddress.ClientPackageRowID,
                    CheckFamilyRowID = item.PQAddress.CheckFamilyRowID,
                    SubCheckRowID = item.PQAddress.SubCheckRowID,
                    SubCheckName = item.PQAddress.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQAddress.UniqueComponentID,
                    CheckStatus = item.PQAddress.CheckStatus,
                    ReWorkCheckStatus = item.PQAddress.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    Partner = db.MasterVendors.Where(t => t.VendorRowID == item.PTRMgrAllocatedTo).FirstOrDefault().VendorName,
                    Location = item.PQAddress.AV_Add,
                    SecuritasSPOC = item.PQAddress.PQPersonal.PQClientMaster.SpocName,
                }).ToList();
                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

        public VerificationInfoListPagedModel GetCandidateAddressListForTLAllocationByMgr1(int pageNo, int pageSize, string sort, string sortDir, string Search = "", string department = "", string statusid = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                DataTable dt = new DataTable();
                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                //if (!string.IsNullOrEmpty(Search))
                //{
                //    dt = cc.getDashboardOperationTLDetail(department, teamMemerRowId, statusid, Search);
                //}
                if (!string.IsNullOrEmpty(Search) || ClientRowID > 0)
                {
                    string ClientId = "";
                    if (ClientRowID == 0)
                    {
                        ClientId = null;
                    }
                    else
                    {
                        ClientId = ClientRowID.ToString();
                    }
                    dt = cc.getDashboardOperationTLDetail(department, teamMemerRowId, statusid, Search, ClientId);
                }

                else
                {
                    dt = cc.getDashboardOperationTLDetail(department, teamMemerRowId, statusid, "");
                }
                // ds = cc.getCasewiseSummaryDetail(ClientRowID, CaseStatus,ClientUserRowID);
                List<VerificationViewModel> lmd = new List<VerificationViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        lmd.Add(new VerificationViewModel
