        //Address TeamLeader
        public VerificationInfoListPagedModel GetCandidateAddressListByDepartmentTeamLeader(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte dtm = 0, byte dtmqc = 0, short AllocateToTM = 0, short AllocateToTMQC = 0, byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "", short State = 0, short City = 0, short Partner = 0)
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                //IQueryable<PQAddress> data = db.PQAddresss.Include("PQPersonal").Include("PQClientMaster").Where(p => p.TLAllocatedTo == teamMemerRowId);
                IQueryable<PQAddressStatus> data = db.PQAddressStatus.Include("PQAddress").Where(p => p.TLAllocatedTo == teamMemerRowId);

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQAddress.ClientRowID == ClientRowID);
                }

                //if (!string.IsNullOrEmpty(CheckStatus))
                //{
                //    data = data.Where(p => p.TLCheckStatus == CheckStatus);
                //}

                if (dtm > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo > 0);
                }

                if (dtmqc > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo > 0);
                }

                //if (AllocateToTM > 0)
                //{
                //    data = data.Where(b => b.TMAllocatedTo == AllocateToTM);
                //}

                //if (AllocateToTMQC > 0)
                //{
                //    data = data.Where(b => b.TMQCAllocatedTo == AllocateToTMQC);
                //}

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQAddress.PQPersonal.Name + " " + b.PQAddress.PQPersonal.MiddleName + " " + b.PQAddress.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQAddress.PQPersonal.ClientRefID == Search || b.PQAddress.AV_Sec_Ref_No == Search || b.PQAddress.CheckStatus == Search || b.PQAddress.UniqueComponentID == Search || b.PQAddress.PQPersonal.CandidateCode == Search);
                }
                if (!string.IsNullOrEmpty(CheckStatus))
                {

                    if (CheckStatus == "Allocated")
                    {
                        data = data.Where(b => b.TMAllocatedTo > 0 && b.TMQCAllocatedTo > 0);
                    }
                    if (CheckStatus == "NonAllocated")
                    {
                        data = data.Where(b => b.TMAllocatedTo == 0 && b.TMQCAllocatedTo == 0);
                    }
                    if (CheckStatus == "Initiated")
                    {
                        data = data.Where(b => b.TLAllocatedTo > 0);
                    }
                    if (CheckStatus == "NonInitiated")
                    {
                        data = data.Where(b => b.PQAddress.CheckStatus == "WIP");
                    }
                    if (CheckStatus == "RejectionWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Rejected-QC");
                    }
                    if (CheckStatus == "ReOpen")
                    {
                        data = data.Where(b => b.PQAddress.PQPersonal.CaseStatus == "ReOpen");
                    }
                    if (CheckStatus == "Priority")
                    {
                        data = data.Where(b => b.PQAddress.PQPersonal.CaseType == "Priority");
                    }
                    if (CheckStatus == "InsuffWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "Insufficiency")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "PrecallingWIP")
                    {
                        data = data.Where(b => b.PQAddress.CheckStatus == "PrecallingWIP");
                    }
                    if (CheckStatus == "PostcallingWIP")
                    {
                        data = data.Where(b => b.PQAddress.CheckStatus == "PrecallingWIP");
                    }
                    if (CheckStatus == "QCPending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "FundApproval")
                    {
                        data = data.Where(b => b.PQAddress.CheckStatus == "Funds Pending");
                    }
                    if (CheckStatus == "Approvalpending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "Escalated")
                    {
                        data = data.Where(b => b.PQAddress.CheckStatus == "Escalated");
                    }
                    if (CheckStatus == "Closed")
                    {
                        data = data.Where(b => b.RWQCManagerBy > 0);
                    }
                    if (CheckStatus == "OutTAT")
                    {
                        DateTime todayTATDate = DateTime.Now;
                        data = data.Where(b => DbFunctions.TruncateTime(b.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(todayTATDate));
                    }
                }
                if (!string.IsNullOrEmpty(CaseStatus))
                {
                    data = data.Where(b => b.PQAddress.PQPersonal.CaseStatus == CaseStatus);
                }
                if (!string.IsNullOrEmpty(DCheckStatus))
                {
                    data = data.Where(b => b.PQAddress.CheckStatus == DCheckStatus);
                }

                if (State > 0)
                {
                    data = data.Where(b => b.PQAddress.AV_State == State);
                }
                if (City > 0)
                {
                    data = data.Where(b => b.PQAddress.AV_City == City);
                }
                if (Partner > 0)
                {
                    data = data.Where(b => b.PTRMgrAllocatedTo == Partner);
                }
                if (!string.IsNullOrEmpty(RecievingToDate) && !string.IsNullOrEmpty(RecievingFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(RecievingFromDate);
                    DateTime EndDate = Convert.ToDateTime(RecievingToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQAddress.CreatedDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQAddress.CreatedDate) <= EndDate.Date);
                }

                if (!string.IsNullOrEmpty(CompletedToDate) && !string.IsNullOrEmpty(CompletedFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(CompletedFromDate);
                    DateTime EndDate = Convert.ToDateTime(CompletedToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQAddress.InternalOutDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQAddress.InternalOutDate) <= EndDate.Date);
                }

                if (tatdays > 0)
                {
                    data = GetAddressesByTATDays(data, tatdays);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQAddress.PersonalRowID) : data.OrderByDescending(d => d.PQAddress.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.PQAddress.AddressRowID,
                    ClientRowID = item.PQAddress.ClientRowID,
                    ClientName = item.PQAddress.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQAddress.PersonalRowID,
                    PersonalName = item.PQAddress.PQPersonal.Name + " " + item.PQAddress.PQPersonal.MiddleName + " " + item.PQAddress.PQPersonal.LastName,
                    CandidateCode = item.PQAddress.PQPersonal.CandidateCode,//copy
                    InternalOutDate = item.PQAddress.InternalOutDate,
                    ClientRefID = item.PQAddress.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQAddress.AV_Sec_Ref_No,
                    OutDate = item.PQAddress.OutDate,//to
                    ClientPackageRowID = item.PQAddress.ClientPackageRowID,
                    CheckFamilyRowID = item.PQAddress.CheckFamilyRowID,
                    SubCheckRowID = item.PQAddress.SubCheckRowID,
                    SubCheckName = item.PQAddress.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQAddress.UniqueComponentID,
                    CheckStatus = item.PQAddress.CheckStatus,
                    ReWorkCheckStatus = item.PQAddress.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    Partner = db.MasterVendors.Where(t => t.VendorRowID == item.PTRMgrAllocatedTo).FirstOrDefault().VendorName,
                    Location = item.PQAddress.AV_Add,
                    SecuritasSPOC = item.PQAddress.PQPersonal.PQClientMaster.SpocName
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

