        public VerificationInfoListPagedModel GetCandidateAddressListForPTRMgrAllocationByTM(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short StateId = 0, string CheckStatus = "")
