        private IQueryable<PQAddressStatus> GetAddressesByTATDays(IQueryable<PQAddressStatus> data, byte tatdays)
        {
            DateTime todayTATDate = DateTime.Now;
            DateTime totTodaysDue = todayTATDate;
            DateTime totDueinNext2days = todayTATDate.AddDays(2);
            DateTime totInTAT4days = todayTATDate.AddDays(4);
            DateTime totInTAT7days = todayTATDate.AddDays(7);
            DateTime totBT1days = todayTATDate.AddDays(-1);
            DateTime totBT2days = todayTATDate.AddDays(-2);
            DateTime totBT5days = todayTATDate.AddDays(-5);
            DateTime totBT10days = todayTATDate.AddDays(-10);

            // QC Members
            TimeSpan totWIP2Hrs = todayTATDate.AddDays(2).TimeOfDay;
            TimeSpan totWIP6Hrs = todayTATDate.AddDays(6).TimeOfDay;
            TimeSpan totWIP12Hrs = todayTATDate.AddDays(12).TimeOfDay;
            TimeSpan totWIP24Hrs = todayTATDate.AddDays(24).TimeOfDay;
            TimeSpan totWIP24HrsPlus = todayTATDate.AddDays(24).TimeOfDay;
            TimeSpan currentTime = DateTime.Now.TimeOfDay;


            if (tatdays == 1)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) == DbFunctions.TruncateTime(todayTATDate));
            }
            else if (tatdays == 2)
            {
                data = data.Where(t =>
                             DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) > DbFunctions.TruncateTime(todayTATDate) &&
                          DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) <= DbFunctions.TruncateTime(totDueinNext2days));
            }
            else if (tatdays == 3)
            {
                data = data.Where(t =>
                           DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) > DbFunctions.TruncateTime(totDueinNext2days) &&
                          DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) <= DbFunctions.TruncateTime(totInTAT7days));
            }
            else if (tatdays == 4)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) > DbFunctions.TruncateTime(totInTAT7days));
            }
            else if (tatdays == 5)
            {
                data = data.Where(t =>
                            DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) <= DbFunctions.TruncateTime(totBT1days) &&
                        DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) >= DbFunctions.TruncateTime(totBT2days));
            }
            else if (tatdays == 6)
            {
                data = data.Where(t =>
                           DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(totBT2days) &&
                          DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) >= DbFunctions.TruncateTime(totBT5days));
            }
            else if (tatdays == 7)
            {
                data = data.Where(t =>
                            DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(totBT5days) &&
                          DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) >= DbFunctions.TruncateTime(totBT10days));
            }
            else if (tatdays == 8)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(totBT10days));
            }
            else if (tatdays == 15)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(totBT5days));
            }
            else if (tatdays == 16)
            {
                data = data.Where(t =>
                             DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) <= DbFunctions.TruncateTime(totBT1days) &&
                           DbFunctions.TruncateTime(t.PQAddress.InternalOutDate) >= DbFunctions.TruncateTime(totBT5days));
            }

            //QC Members
            else if (tatdays == 10)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) <= currentTime &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP2Hrs);
            }
            else if (tatdays == 11)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP2Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP6Hrs);
            }
            else if (tatdays == 12)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP6Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP12Hrs);
            }
            else if (tatdays == 13)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP12Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP24Hrs);
            }
            else if (tatdays == 14)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP24Hrs);
            }

            return data;
        }

