        //Reference TeamLeader
        public VerificationInfoListPagedModel GetCandidateReferenceListByDepartmentTeamLeader(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte dtm = 0, byte dtmqc = 0, short AllocateToTM = 0, short AllocateToTMQC = 0, byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                IQueryable<PQReferenceStatus> data = db.PQReferenceStatus.Include("PQReference").Where(p => p.TLAllocatedTo == teamMemerRowId);

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQReference.ClientRowID == ClientRowID);
                }

                //if (!string.IsNullOrEmpty(CheckStatus))
                //{
                //    data = data.Where(p => p.PQReference.CheckStatus == CheckStatus);
                //}

                if (dtm > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo > 0);
                }

                if (dtmqc > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo > 0);
                }

                if (AllocateToTM > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo == AllocateToTM);
                }

                if (AllocateToTMQC > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo == AllocateToTMQC);
                }

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQReference.PQPersonal.Name + " " + b.PQReference.PQPersonal.MiddleName + " " + b.PQReference.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQReference.PQPersonal.ClientRefID == Search || b.PQReference.RV_Sec_Ref_Id == Search || b.PQReference.CheckStatus == Search || b.PQReference.UniqueComponentID == Search || b.PQReference.PQPersonal.CandidateCode == Search);
                }
                if (!string.IsNullOrEmpty(CheckStatus))
                {

                    if (CheckStatus == "Allocated")
                    {
                        data = data.Where(t => t.TMAllocatedTo > 0 && t.TMQCAllocatedTo > 0);
                    }
                    if (CheckStatus == "NonAllocated")
                    {
                        data = data.Where(b => b.TLAllocatedTo == 0);
                    }
                    if (CheckStatus == "Initiated")
                    {
                        data = data.Where(b => b.TLAllocatedTo > 0);
                    }
                    if (CheckStatus == "NonInitiated")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "WIP");
                    }
                    if (CheckStatus == "RejectionWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Rejected-QC");
                    }
                    if (CheckStatus == "ReOpen")
                    {
                        data = data.Where(b => b.PQReference.PQPersonal.CaseStatus == "ReOpen");
                    }
                    if (CheckStatus == "Priority")
                    {
                        data = data.Where(b => b.PQReference.PQPersonal.CaseType == "Priority");
                    }
                    if (CheckStatus == "InsuffWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "Insufficiency")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "PrecallingWIP")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "PrecallingWIP");
                    }
                    if (CheckStatus == "PostcallingWIP")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "PrecallingWIP");
                    }
                    if (CheckStatus == "QCPending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "FundApproval")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "Funds Pending");
                    }
                    if (CheckStatus == "Approvalpending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "Escalated")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "Escalated");
                    }
                    if (CheckStatus == "Closed")
                    {
                        data = data.Where(b => b.RWQCManagerBy > 0);
                    }
                    if (CheckStatus == "OutTAT")
                    {
                        DateTime todayTATDate = DateTime.Now;
                        data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.InternalOutDate) < DbFunctions.TruncateTime(todayTATDate));
                    }
                }
                if (!string.IsNullOrEmpty(CaseStatus))
                {
                    data = data.Where(b => b.PQReference.PQPersonal.CaseStatus == CaseStatus);
                }
                if (!string.IsNullOrEmpty(DCheckStatus))
                {
                    data = data.Where(b => b.PQReference.CheckStatus == DCheckStatus);
                }
                if (!string.IsNullOrEmpty(RecievingToDate) && !string.IsNullOrEmpty(RecievingFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(RecievingFromDate);
                    DateTime EndDate = Convert.ToDateTime(RecievingToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.CreatedDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQReference.CreatedDate) <= EndDate.Date);
                }

                if (!string.IsNullOrEmpty(CompletedToDate) && !string.IsNullOrEmpty(CompletedFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(CompletedFromDate);
                    DateTime EndDate = Convert.ToDateTime(CompletedToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.InternalOutDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQReference.InternalOutDate) <= EndDate.Date);
                }
                if (tatdays > 0)
                {
                    data = GetReferencesByTATDays(data, tatdays);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQReference.PersonalRowID) : data.OrderByDescending(d => d.PQReference.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.ReferenceRowID,
                    ClientRowID = item.PQReference.ClientRowID,
                    ClientName = item.PQReference.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQReference.PersonalRowID,
                    PersonalName = item.PQReference.PQPersonal.Name + " " + item.PQReference.PQPersonal.MiddleName + " " + item.PQReference.PQPersonal.LastName,
                    CandidateCode = item.PQReference.PQPersonal.CandidateCode,
                    InternalOutDate = item.PQReference.InternalOutDate,
                    ClientRefID = item.PQReference.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQReference.RV_Sec_Ref_Id,
                    OutDate = item.PQReference.OutDate,
                    ClientPackageRowID = item.PQReference.ClientPackageRowID,
                    CheckFamilyRowID = item.PQReference.CheckFamilyRowID,
                    SubCheckRowID = item.PQReference.SubCheckRowID,
                    SubCheckName = item.PQReference.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQReference.UniqueComponentID,
                    CheckStatus = item.PQReference.CheckStatus,
                    ReWorkCheckStatus = item.PQReference.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    AllocatedQCName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMQCAllocatedTo).FirstOrDefault().TMFirstName,
                    SecuritasSPOC = item.PQReference.PQPersonal.PQClientMaster.SpocName
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

