        public VerificationInfoListPagedModel GetCandidateReferenceListForTMQCAllocationByTL(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", string ReAllocation = "", short AllocateTM = 0, short AllocateTMQC = 0)
        {
            try 
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                IQueryable<PQReferenceStatus> data = db.PQReferenceStatus.Include("PQReference").Where(p => p.TLAllocatedTo == teamMemerRowId);
                if (ReAllocation == "ReAllocation")
                {
                    //data = data.Where(p => p.TMAllocatedTo == 0 && p.TMQCAllocatedTo == 0 && !p.TMCheckStatus.Equals("Completed") && !p.TMQCCheckStatus.Equals("Completed-QC"));
                    data = data.Where(p => p.TMAllocatedTo > 0 && p.TMQCAllocatedTo > 0 && !p.TMCheckStatus.Equals("Completed") && !p.TMQCCheckStatus.Equals("Completed-QC"));
                }
                else
                {
                    data = data.Where(p => p.TMAllocatedTo == 0 && p.TMQCAllocatedTo == 0);
                }
                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQReference.ClientRowID == ClientRowID);
                }
                if (AllocateTM > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo == AllocateTM);
                }
                if (AllocateTMQC > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo == AllocateTMQC);
                }
                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQReference.PQPersonal.Name + " " + b.PQReference.PQPersonal.MiddleName + " " + b.PQReference.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQReference.PQPersonal.ClientRefID == Search || b.PQReference.RV_Sec_Ref_Id == Search || b.PQReference.CheckStatus == Search || b.PQReference.UniqueComponentID == Search || b.PQReference.PQPersonal.CandidateCode == Search);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQReference.PersonalRowID) : data.OrderByDescending(d => d.PQReference.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.ReferenceRowID,
                    ClientRowID = item.PQReference.ClientRowID,
                    ClientName = item.PQReference.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQReference.PersonalRowID,
                    PersonalName = item.PQReference.PQPersonal.Name + " " + item.PQReference.PQPersonal.MiddleName + " " + item.PQReference.PQPersonal.LastName,
                    CandidateCode = item.PQReference.PQPersonal.CandidateCode,
                    InternalOutDate = item.PQReference.InternalOutDate,
                    ClientRefID = item.PQReference.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQReference.RV_Sec_Ref_Id,
                    OutDate = item.PQReference.OutDate,
                    ClientPackageRowID = item.PQReference.ClientPackageRowID,
                    CheckFamilyRowID = item.PQReference.CheckFamilyRowID,
                    SubCheckRowID = item.PQReference.SubCheckRowID,
                    SubCheckName = item.PQReference.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQReference.UniqueComponentID,
                    CheckStatus = item.PQReference.CheckStatus,
                    ReWorkCheckStatus = item.PQReference.ReWorkCheckStatus,
                    AllocatedTMName = db.WebUsers.Where(t => t.TeamMemberRoWID == item.TMAllocatedTo).FirstOrDefault().CRPUserName,
                    AllocatedQCName = db.WebUsers.Where(t => t.TeamMemberRoWID == item.TMQCAllocatedTo).FirstOrDefault().CRPUserName,
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

        public VerificationInfoListPagedModel GetCandidateReferenceListForTMQCAllocationByTL1(int pageNo, int pageSize, string sort, string sortDir, string Search = "", string department = "", string statusid = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", string ReAllocation = "", short AllocateTM = 0, short AllocateTMQC = 0)
        {
            try
            {
                if (pageNo < 0)
                {
