        public VerificationInfoListPagedModel GetCandidateReferenceListForTMMQC(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                IQueryable<PQReferenceStatus> data = db.PQReferenceStatus.Include("PQReference").Where(p => p.TMQCAllocatedTo == teamMemerRowId);

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQReference.ClientRowID == ClientRowID);
                }

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQReference.PQPersonal.Name + " " + b.PQReference.PQPersonal.MiddleName + " " + b.PQReference.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQReference.PQPersonal.ClientRefID == Search || b.PQReference.RV_Sec_Ref_Id == Search || b.PQReference.CheckStatus == Search || b.PQReference.UniqueComponentID == Search || b.PQReference.PQPersonal.CandidateCode == Search);
                }
                if (!string.IsNullOrEmpty(CheckStatus))
                {
                    if (CheckStatus == "New")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "WIP")
                    {
                        data = data.Where(p => p.TMQCCheckStatus == "Completed" || p.TMQCCheckStatus == "Insufficent" || p.TMQCCheckStatus == "Funds Pending");
                    }
                    if (CheckStatus == "RejectionWIP")
                    {
                        data = data.Where(b => b.TMCheckStatus == "Rejected");
                    }
                    if (CheckStatus == "ReOpen")
                    {
                        data = data.Where(b => b.PQReference.PQPersonal.CaseStatus == "ReOpen");
                    }
                    if (CheckStatus == "Priority")
                    {
                        data = data.Where(b => b.PQReference.PQPersonal.CaseType == "Priority");
                    }
                    if (CheckStatus == "InsuffWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent");
                    }

                    if (CheckStatus == "FundApproval")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "Funds Pending");
                    }
                    if (CheckStatus == "ReviewResolved")
                    {
                        data = data.Where(b => b.PQReference.CheckStatus == "ReviewResolved");
                    }
                    if (CheckStatus == "InsufficiencyRaised")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }

                    if (CheckStatus == "ApprovalPending")
                    {
                        data = data.Where(p => p.TMQCCheckStatus == "Completed" || p.TMQCCheckStatus == "Insufficent" || p.TMQCCheckStatus == "Funds Pending");
                    }

                    if (CheckStatus == "QCApproval")
                    {
                        data = data.Where(p => p.TMQCCheckStatus == "Completed-QC" || p.TMQCCheckStatus == "Insufficent-QC" || p.TMQCCheckStatus == "Funds Pending-QC");
                    }
                    if (CheckStatus == "OutTAT")
                    {
                        DateTime todayTATDate = DateTime.Now;
                        data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.InternalOutDate) < DbFunctions.TruncateTime(todayTATDate));
                    }
                }
                if (!string.IsNullOrEmpty(CaseStatus))
                {
                    data = data.Where(b => b.PQReference.PQPersonal.CaseStatus == CaseStatus);
                }
                if (!string.IsNullOrEmpty(DCheckStatus))
                {
                    data = data.Where(b => b.PQReference.CheckStatus == DCheckStatus);
                }
                if (!string.IsNullOrEmpty(RecievingToDate) && !string.IsNullOrEmpty(RecievingFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(RecievingFromDate);
                    DateTime EndDate = Convert.ToDateTime(RecievingToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.CreatedDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQReference.CreatedDate) <= EndDate.Date);
                }

                if (!string.IsNullOrEmpty(CompletedToDate) && !string.IsNullOrEmpty(CompletedFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(CompletedFromDate);
                    DateTime EndDate = Convert.ToDateTime(CompletedToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQReference.InternalOutDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQReference.InternalOutDate) <= EndDate.Date);
                }

                if (tatdays > 0)
                {
                    data = GetReferencesByTATDays(data, tatdays);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.ReferenceStatusRowID) : data.OrderByDescending(d => d.ReferenceStatusRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.ReferenceRowID,
                    ClientRowID = item.PQReference.ClientRowID,
                    ClientName = item.PQReference.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQReference.PersonalRowID,
                    PersonalName = item.PQReference.PQPersonal.Name + " " + item.PQReference.PQPersonal.MiddleName + " " + item.PQReference.PQPersonal.LastName,
                    CandidateCode = item.PQReference.PQPersonal.CandidateCode,
                    InternalOutDate = item.PQReference.InternalOutDate,
                    ClientRefID = item.PQReference.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQReference.RV_Sec_Ref_Id,
                    OutDate = item.PQReference.OutDate,
                    ClientPackageRowID = item.PQReference.ClientPackageRowID,
                    CheckFamilyRowID = item.PQReference.CheckFamilyRowID,
                    SubCheckRowID = item.PQReference.SubCheckRowID,
                    SubCheckName = item.PQReference.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQReference.UniqueComponentID,
                    CheckStatus = item.PQReference.CheckStatus,
                    ReWorkCheckStatus = item.PQReference.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    SecuritasSPOC = item.PQReference.PQPersonal.PQClientMaster.SpocName
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

        private IQueryable<PQReferenceStatus> GetReferencesByTATDays(IQueryable<PQReferenceStatus> data, byte tatdays)
        {
            DateTime todayTATDate = DateTime.Now;
            DateTime totTodaysDue = todayTATDate;
            DateTime totDueinNext2days = todayTATDate.AddDays(2);
            DateTime totInTAT4days = todayTATDate.AddDays(4);
            DateTime totInTAT7days = todayTATDate.AddDays(7);
            DateTime totBT1days = todayTATDate.AddDays(-1);
            DateTime totBT2days = todayTATDate.AddDays(-2);
            DateTime totBT5days = todayTATDate.AddDays(-5);
            DateTime totBT10days = todayTATDate.AddDays(-10);

            // QC Members
            TimeSpan totWIP2Hrs = todayTATDate.AddDays(2).TimeOfDay;
            TimeSpan totWIP6Hrs = todayTATDate.AddDays(6).TimeOfDay;
            TimeSpan totWIP12Hrs = todayTATDate.AddDays(12).TimeOfDay;
            TimeSpan totWIP24Hrs = todayTATDate.AddDays(24).TimeOfDay;
            TimeSpan totWIP24HrsPlus = todayTATDate.AddDays(24).TimeOfDay;
            TimeSpan currentTime = DateTime.Now.TimeOfDay;


            if (tatdays == 1)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQReference.InternalOutDate) == DbFunctions.TruncateTime(todayTATDate));
            }
            else if (tatdays == 2)
            {
                data = data.Where(t =>
                             DbFunctions.TruncateTime(t.PQReference.InternalOutDate) > DbFunctions.TruncateTime(todayTATDate) &&
                          DbFunctions.TruncateTime(t.PQReference.InternalOutDate) <= DbFunctions.TruncateTime(totDueinNext2days));
            }
            else if (tatdays == 3)
            {
                data = data.Where(t =>
                           DbFunctions.TruncateTime(t.PQReference.InternalOutDate) > DbFunctions.TruncateTime(totDueinNext2days) &&
                          DbFunctions.TruncateTime(t.PQReference.InternalOutDate) <= DbFunctions.TruncateTime(totInTAT7days));
            }
            else if (tatdays == 4)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQReference.InternalOutDate) > DbFunctions.TruncateTime(totInTAT7days));
            }
            else if (tatdays == 5)
            {
                data = data.Where(t =>
                            DbFunctions.TruncateTime(t.PQReference.InternalOutDate) <= DbFunctions.TruncateTime(totBT1days) &&
                        DbFunctions.TruncateTime(t.PQReference.InternalOutDate) >= DbFunctions.TruncateTime(totBT2days));
            }
            else if (tatdays == 6)
            {
                data = data.Where(t =>
                           DbFunctions.TruncateTime(t.PQReference.InternalOutDate) < DbFunctions.TruncateTime(totBT2days) &&
                          DbFunctions.TruncateTime(t.PQReference.InternalOutDate) >= DbFunctions.TruncateTime(totBT5days));
            }
            else if (tatdays == 7)
            {
                data = data.Where(t =>
                            DbFunctions.TruncateTime(t.PQReference.InternalOutDate) < DbFunctions.TruncateTime(totBT5days) &&
                          DbFunctions.TruncateTime(t.PQReference.InternalOutDate) >= DbFunctions.TruncateTime(totBT10days));
            }
            else if (tatdays == 8)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQReference.InternalOutDate) < DbFunctions.TruncateTime(totBT10days));
            }
            else if (tatdays == 15)
            {
                data = data.Where(t => DbFunctions.TruncateTime(t.PQReference.InternalOutDate) < DbFunctions.TruncateTime(totBT5days));
            }
            else if (tatdays == 16)
            {
                data = data.Where(t =>
                             DbFunctions.TruncateTime(t.PQReference.InternalOutDate) <= DbFunctions.TruncateTime(totBT1days) &&
                           DbFunctions.TruncateTime(t.PQReference.InternalOutDate) >= DbFunctions.TruncateTime(totBT5days));
            }

            //QC Members
            else if (tatdays == 10)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) <= currentTime &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP2Hrs);
            }
            else if (tatdays == 11)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP2Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP6Hrs);
            }
            else if (tatdays == 12)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP6Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP12Hrs);
            }
            else if (tatdays == 13)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP12Hrs &&
                                 DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) < totWIP24Hrs);
            }
            else if (tatdays == 14)
            {
                data = data.Where(t => DbFunctions.CreateTime(t.TMQCAllocatedDate.Value.Hour, t.TMQCAllocatedDate.Value.Minute, 0) > totWIP24Hrs);
            }

            return data;
        }

