        public VerificationInfoListPagedModel GetCandidateIdentityListForTLAllocationByMgr(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                IQueryable<PQNationalIdentityStatus> data = db.PQNationalIdentityStatus.Include("PQNationalIdentity").Where(p => p.MgrAllocatedTo == teamMemerRowId && p.TLAllocatedTo == 0);

                if (!string.IsNullOrEmpty(CheckStatus))
                {
                    data = data.Where(p => p.MgrCheckStatus == CheckStatus);
                }

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQNationalIdentity.ClientRowID == ClientRowID);
                }

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQNationalIdentity.PQPersonal.Name + " " + b.PQNationalIdentity.PQPersonal.MiddleName + " " + b.PQNationalIdentity.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQNationalIdentity.PQPersonal.ClientRefID == Search || b.PQNationalIdentity.NIC_Sec_Ref_Id == Search || b.PQNationalIdentity.CheckStatus == Search || b.PQNationalIdentity.UniqueComponentID == Search || b.PQNationalIdentity.PQPersonal.CandidateCode == Search);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQNationalIdentity.PersonalRowID) : data.OrderByDescending(d => d.PQNationalIdentity.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.NationalIdentityRowID,
                    ClientRowID = item.PQNationalIdentity.ClientRowID,
                    ClientName = item.PQNationalIdentity.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQNationalIdentity.PersonalRowID,
                    PersonalName = item.PQNationalIdentity.PQPersonal.Name + " " + item.PQNationalIdentity.PQPersonal.MiddleName + " " + item.PQNationalIdentity.PQPersonal.LastName,
                    CandidateCode = item.PQNationalIdentity.PQPersonal.CandidateCode,
                    InternalOutDate = item.PQNationalIdentity.InternalOutDate,
                    ClientRefID = item.PQNationalIdentity.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQNationalIdentity.NIC_Sec_Ref_Id,
                    OutDate = item.PQNationalIdentity.OutDate,
                    ClientPackageRowID = item.PQNationalIdentity.ClientPackageRowID,
                    CheckFamilyRowID = item.PQNationalIdentity.CheckFamilyRowID,
                    SubCheckRowID = item.PQNationalIdentity.SubCheckRowID,
                    SubCheckName = item.PQNationalIdentity.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQNationalIdentity.UniqueComponentID,
                    CheckStatus = item.PQNationalIdentity.CheckStatus,
                    ReWorkCheckStatus = item.PQNationalIdentity.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    AllocatedQCName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMQCAllocatedTo).FirstOrDefault().TMFirstName,
                    SecuritasSPOC = item.PQNationalIdentity.PQPersonal.PQClientMaster.SpocName,
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

