        //Special Check TeamLeader
        public VerificationInfoListPagedModel GetCandidateSpecialCheckListByTeamLeader(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte dtm = 0, byte dtmqc = 0, short AllocateToTM = 0, short AllocateToTMQC = 0, byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                IQueryable<PQSpecialCheckStatus> data = db.PQSpecialCheckStatus.Include("PQSpecialCheck").Where(p => p.TLAllocatedTo == teamMemerRowId);

                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQSpecialCheck.ClientRowID == ClientRowID);
                }

                if (dtm > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo > 0);
                }

                if (dtmqc > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo > 0);
                }

                if (AllocateToTM > 0)
                {
                    data = data.Where(b => b.TMAllocatedTo == AllocateToTM);
                }

                if (AllocateToTMQC > 0)
                {
                    data = data.Where(b => b.TMQCAllocatedTo == AllocateToTMQC);
                }

                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (b.PQSpecialCheck.PQPersonal.Name + " " + b.PQSpecialCheck.PQPersonal.MiddleName + " " + b.PQSpecialCheck.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) || b.PQSpecialCheck.PQPersonal.ClientRefID == Search || b.PQSpecialCheck.SC_SecuritasID == Search || b.PQSpecialCheck.CheckStatus == Search || b.PQSpecialCheck.UniqueComponentID == Search || b.PQSpecialCheck.PQPersonal.CandidateCode == Search);
                }
                if (!string.IsNullOrEmpty(CheckStatus))
                {
                    if (CheckStatus == "Allocated")
                    {
                        data = data.Where(t => t.TMAllocatedTo > 0 && t.TMQCAllocatedTo > 0);
                    }
                    if (CheckStatus == "NonAllocated")
                    {
                        data = data.Where(b => b.TLAllocatedTo == 0);
                    }
                    if (CheckStatus == "RejectionWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Rejected-QC");
                    }
                    if (CheckStatus == "ReOpen")
                    {
                        data = data.Where(b => b.PQSpecialCheck.PQPersonal.CaseStatus == "ReOpen");
                    }
                    if (CheckStatus == "Priority")
                    {
                        data = data.Where(b => b.PQSpecialCheck.PQPersonal.CaseType == "Priority");
                    }
                    if (CheckStatus == "InsuffWIP")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "Insufficiency")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                    }
                    if (CheckStatus == "QCPending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "FundApproval")
                    {
                        data = data.Where(b => b.PQSpecialCheck.CheckStatus == "Funds Pending");
                    }
                    if (CheckStatus == "Approvalpending")
                    {
                        data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                    }
                    if (CheckStatus == "Escalated")
                    {
                        data = data.Where(b => b.PQSpecialCheck.CheckStatus == "Escalated");
                    }
                    if (CheckStatus == "Closed")
                    {
                        data = data.Where(b => b.RWQCManagerBy > 0);
                    }
                    if (CheckStatus == "OutTAT")
                    {
                        DateTime todayTATDate = DateTime.Now;
                        data = data.Where(b => DbFunctions.TruncateTime(b.PQSpecialCheck.InternalOutDate) < DbFunctions.TruncateTime(todayTATDate));
                    }
                }
                if (!string.IsNullOrEmpty(CaseStatus))
                {
                    data = data.Where(b => b.PQSpecialCheck.PQPersonal.CaseStatus == CaseStatus);
                }
                if (!string.IsNullOrEmpty(DCheckStatus))
                {
                    data = data.Where(b => b.PQSpecialCheck.CheckStatus == DCheckStatus);
                }
                if (!string.IsNullOrEmpty(RecievingToDate) && !string.IsNullOrEmpty(RecievingFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(RecievingFromDate);
                    DateTime EndDate = Convert.ToDateTime(RecievingToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQSpecialCheck.CreatedDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQSpecialCheck.CreatedDate) <= EndDate.Date);
                }

                if (!string.IsNullOrEmpty(CompletedToDate) && !string.IsNullOrEmpty(CompletedFromDate))
                {
                    DateTime startDate = Convert.ToDateTime(CompletedFromDate);
                    DateTime EndDate = Convert.ToDateTime(CompletedToDate);

                    data = data.Where(b => DbFunctions.TruncateTime(b.PQSpecialCheck.InternalOutDate) >= startDate.Date && DbFunctions.TruncateTime(b.PQSpecialCheck.InternalOutDate) <= EndDate.Date);
                }
                if (tatdays > 0)
                {
                    data = GetSpecialCheckByTATDays(data, tatdays);
                }

                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.PQSpecialCheck.PersonalRowID) : data.OrderByDescending(d => d.PQSpecialCheck.PersonalRowID);
                        break;
                }

                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                model.PageSize = pageSize;
                model.TotalRecords = data.Count();
                model.PQVerificationInfo = data.Skip((pageNo - 1) * pageSize).Take(pageSize).Select(item => new VerificationViewModel
                {
                    VerificationRowID = item.SpecialCheckRowId,
                    ClientRowID = item.PQSpecialCheck.ClientRowID,
                    ClientName = item.PQSpecialCheck.PQClientMaster.MasterAbbreviation.ClientName,
                    PersonalRowID = item.PQSpecialCheck.PersonalRowID,
                    PersonalName = item.PQSpecialCheck.PQPersonal.Name + " " + item.PQSpecialCheck.PQPersonal.MiddleName + " " + item.PQSpecialCheck.PQPersonal.LastName,
                    CandidateCode = item.PQSpecialCheck.PQPersonal.CandidateCode,
                    InternalOutDate = item.PQSpecialCheck.InternalOutDate,
                    ClientRefID = item.PQSpecialCheck.PQPersonal.ClientRefID,
                    CompanyRefNo = item.PQSpecialCheck.SC_SecuritasID,
                    OutDate = item.PQSpecialCheck.OutDate,
                    ClientPackageRowID = item.PQSpecialCheck.ClientPackageRowID,
                    CheckFamilyRowID = item.PQSpecialCheck.CheckFamilyRowID,
                    SubCheckRowID = item.PQSpecialCheck.SubCheckRowID,
                    SubCheckName = item.PQSpecialCheck.MasterSubCheckFamily.SubCheckName,
                    UniqueComponentID = item.PQSpecialCheck.UniqueComponentID,
                    CheckStatus = item.PQSpecialCheck.CheckStatus,
                    ReWorkCheckStatus = item.PQSpecialCheck.ReWorkCheckStatus,
                    AllocatedTMName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMAllocatedTo).FirstOrDefault().TMFirstName,
                    AllocatedQCName = db.TeamMembers.Where(t => t.TeamMemberRowID == item.TMQCAllocatedTo).FirstOrDefault().TMFirstName,
                    SecuritasSPOC = item.PQSpecialCheck.PQPersonal.PQClientMaster.SpocName
                }).ToList();

                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }

