        #region ***** Fund Pending Checks Update By Department TL *****

        public void FundPendingChecksUpdateByDepartmentTL(FundPendingApprovalViewModel model)
        {
            using (DataContext context = new DataContext())
            {
                using (DbContextTransaction transaction = context.Database.BeginTransaction())
                {
                    try
                    {
                        #region UpdateAddressInfo
                        if (model.CheckFamilyRowID == 2)
                        {
                            context.PQAddresss.Single(c => c.AddressRowID == model.VerificationRowID).CheckStatus = model.CheckStatus;
                            context.PQAddresss.Single(c => c.AddressRowID == model.VerificationRowID).ModifiedBy = model.ModifiedBy;
                            context.PQAddresss.Single(c => c.AddressRowID == model.VerificationRowID).ModifiedDate = model.ModifiedDate;
                            context.SaveChanges();

                            #region Save Check Status

                            int statusId = context.PQAddressStatus.Where(p => p.AddressRowID == model.VerificationRowID).FirstOrDefault().AddressStatusRowID;

                            context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).TMCheckStatus = model.CheckStatus;
                            context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).TMQCCheckStatus = "";

                            context.SaveChanges();

                            #endregion

                        }
                        #endregion

                        #region UpdateEmploymentInfo
                        if (model.CheckFamilyRowID == 12)
                        {
