                            int statusId = context.PQEducationStatus.Where(p => p.EducationRowId == model.VerificationRowID).FirstOrDefault().EducationStatusRowID;

                            context.PQEducationStatus.Single(c => c.EducationStatusRowID == statusId).TMCheckStatus = model.CheckStatus;
                            context.PQEducationStatus.Single(c => c.EducationStatusRowID == statusId).TMQCCheckStatus = "";

                            context.SaveChanges();

                            #endregion
                        }
                        #endregion

                        #region UpdateCriminalInfo

                        if (model.CheckFamilyRowID == 5)
                        {
                            context.PQCriminals.Single(c => c.CriminalRowId == model.VerificationRowID).CheckStatus = model.CheckStatus;
                            context.PQCriminals.Single(c => c.CriminalRowId == model.VerificationRowID).ModifiedBy = model.ModifiedBy;
                            context.PQCriminals.Single(c => c.CriminalRowId == model.VerificationRowID).ModifiedDate = model.ModifiedDate;
                            context.SaveChanges();

                            #region Save Check Status

                            int statusId = context.PQCriminalStatus.Where(p => p.CriminalRowId == model.VerificationRowID).FirstOrDefault().CriminalStatusRowID;

                            context.PQCriminalStatus.Single(c => c.CriminalStatusRowID == statusId).TMCheckStatus = model.CheckStatus;
                            context.PQCriminalStatus.Single(c => c.CriminalStatusRowID == statusId).TMQCCheckStatus = "";

                            context.SaveChanges();

                            #endregion
                        }
                        #endregion

                        #region UpdateNationalIdentityInfo

                        if (model.CheckFamilyRowID == 26)
                        {
                            context.PQNationalIdentities.Single(c => c.NationalIdentityRowID == model.VerificationRowID).CheckStatus = model.CheckStatus;
                            context.PQNationalIdentities.Single(c => c.NationalIdentityRowID == model.VerificationRowID).ModifiedBy = model.ModifiedBy;
                            context.PQNationalIdentities.Single(c => c.NationalIdentityRowID == model.VerificationRowID).ModifiedDate = model.ModifiedDate;
                            context.SaveChanges();

                            #region Save Check Status

                            int statusId = context.PQNationalIdentityStatus.Where(p => p.NationalIdentityRowID == model.VerificationRowID).FirstOrDefault().NationalIdentityStatusRowID;

                            context.PQNationalIdentityStatus.Single(c => c.NationalIdentityStatusRowID == statusId).TMCheckStatus = model.CheckStatus;
                            context.PQNationalIdentityStatus.Single(c => c.NationalIdentityStatusRowID == statusId).TMQCCheckStatus = "";

                            context.SaveChanges();

                            #endregion
                        }
                        #endregion

                        #region UpdateReferenceInfo

                        if (model.CheckFamilyRowID == 30)
                        {
                            context.PQReferences.Single(c => c.ReferenceRowID == model.VerificationRowID).CheckStatus = model.CheckStatus;
                            context.PQReferences.Single(c => c.ReferenceRowID == model.VerificationRowID).ModifiedBy = model.ModifiedBy;
                            context.PQReferences.Single(c => c.ReferenceRowID == model.VerificationRowID).ModifiedDate = model.ModifiedDate;
                            context.SaveChanges();

                            #region Save Check Status

                            int statusId = context.PQReferenceStatus.Where(p => p.ReferenceRowID == model.VerificationRowID).FirstOrDefault().ReferenceStatusRowID;

                            context.PQReferenceStatus.Single(c => c.ReferenceStatusRowID == statusId).TMCheckStatus = model.CheckStatus;
                            context.PQReferenceStatus.Single(c => c.ReferenceStatusRowID == statusId).TMQCCheckStatus = "";

                            context.SaveChanges();

                            #endregion
                        }
                        #endregion                       

                        transaction.Commit();
                    }
                    catch (Exception)
                    {
                        transaction.Rollback();
                        throw;
                    }
                }
            }
        }

