        public VerificationInfoListPagedModel GetRWApprovalCheckListForDepartmentTL(int pageNo, int pageSize, string sort, string sortDir, string Search = "", short ClientRowID = 0, short TeamMemberID = 0)
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                //PQAddresss
                IQueryable<PQAddressStatus> data = db.PQAddressStatus.Include("PQAddress").Where(p => p.TLCheckStatus == "RW-Approval-TL" && p.PQAddress.CheckStatus == "RW-Approval-TL" && p.TLAllocatedTo == TeamMemberID);
                if (ClientRowID > 0)
                {
                    data = data.Where(b => b.PQAddress.ClientRowID == ClientRowID);
                }
                switch (sort)
                {
                    default:
                        data = sortDir == "asc" ? data.OrderBy(d => d.AddressStatusRowID) : data.OrderByDescending(d => d.AddressStatusRowID);
                        break;
                }
                if (!string.IsNullOrEmpty(Search))
                {
                    data = data.Where(b => (
                    b.PQAddress.PQPersonal.Name + " " + b.PQAddress.PQPersonal.MiddleName + " " + b.PQAddress.PQPersonal.LastName).ToString().Replace(" ", "").Contains(Search.Replace(" ", "")) ||
                    b.PQAddress.PQPersonal.ClientRefID == Search ||
                    b.PQAddress.AV_Sec_Ref_No == Search ||
                    b.PQAddress.UniqueComponentID == Search ||
                    b.PQAddress.PQPersonal.CandidateCode == Search);
