        public void UpdateAddressCheckRejectionByMgrOrTL(ViewAddressViewModel model, string designationName, short RWMgrID = 0)
        {
            using (DataContext context = new DataContext())
            {
                using (DbContextTransaction transaction = context.Database.BeginTransaction())
                {
                    try
                    {
                        if (model != null)
                        {
                            int statusId = context.PQAddressStatus.Where(p => p.AddressRowID == model.AddressRowID).FirstOrDefault().AddressStatusRowID;

                            var AddressVer = context.PQAddressVers.Where(c => c.AddressRowID == model.AddressRowID).Select(p => new { AddressVerRowID = p.AddressVerRowID, ColorName = p.ColorName, Severity = p.Severity }).FirstOrDefault();

                            if (model.CheckStatus == "Rejected")
                            {
                                context.PQAddresss.Single(c => c.AddressRowID == model.AddressRowID).CheckStatus = "Completed-TM";
                                context.SaveChanges();

                                context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).TMQCCheckStatus = "Completed";
                                context.SaveChanges();

                                context.PQAddressVers.Single(c => c.AddressVerRowID == AddressVer.AddressVerRowID).CheckStatus = "Completed";
                                context.SaveChanges();

                            }
                            else
                            {
                                if (AddressVer.ColorName == "Red")
                                {
                                    if (designationName == "Manager-Add")
                                    {
                                        short TemaMember = context.PQAddresss.Find(model.AddressRowID).PQPersonal.RWQCManagerTo;
                                        if (TemaMember == 0)
                                        {
                                            context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCMgrCaseStatus = "Allocated-Mgr";
                                            context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCManagerTo = RWMgrID;
                                            context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCManagerDate = DateTime.Now;
                                            context.SaveChanges();
                                        }

                                        context.PQAddresss.Single(c => c.AddressRowID == model.AddressRowID).CheckStatus = "Allocated-RWQC";
                                        context.SaveChanges();

                                        context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCMgrCheckStatus = "Allocated-RWQC";
                                        context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCManagerBy = RWMgrID;
                                        context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCManagerDate = DateTime.Now;
                                        context.SaveChanges();
                                    }
                                    else
                                    {
                                        context.PQAddresss.Single(c => c.AddressRowID == model.AddressRowID).CheckStatus = "RW-Approval-Mgr";
                                        context.SaveChanges();

                                        context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).MgrCheckStatus = "RW-Approval-Mgr";
                                        context.SaveChanges();
                                    }
                                }
                                else
                                {
                                    short TemaMember = context.PQAddresss.Find(model.AddressRowID).PQPersonal.RWQCManagerTo;
                                    if (TemaMember == 0)
                                    {
                                        context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCMgrCaseStatus = "Allocated-Mgr";
                                        context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCManagerTo = RWMgrID;
                                        context.PQPersonals.Single(c => c.PersonalRowID == model.PersonalRowID).RWQCManagerDate = DateTime.Now;
                                        context.SaveChanges();
                                    }

                                    context.PQAddresss.Single(c => c.AddressRowID == model.AddressRowID).CheckStatus = "Allocated-RWQC";
                                    context.SaveChanges();

                                    context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCMgrCheckStatus = "Allocated-RWQC";
                                    context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCManagerBy = RWMgrID;
                                    context.PQAddressStatus.Single(c => c.AddressStatusRowID == statusId).RWQCManagerDate = DateTime.Now;
                                    context.SaveChanges();

                                }
                            }

                            transaction.Commit();
                        }
                    }
                    catch (Exception)
                    {
                        transaction.Rollback();
                        throw;
                    }
                }
            }
        }

