        public VerificationInfoListPagedModel GetExportCandidateAddressListByDepartmentManager(string Designation = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte AllocatedToTL = 0, byte tatdays = 0, string DCheckStatus = "", string CaseStatus = "")
        {
            try
            {

                IQueryable<PQAddressStatus> data = db.PQAddressStatus.Include("PQAddress");

                if (Designation == "Manager-Add")
                {
                    data = data.Where(p => p.MgrAllocatedTo == teamMemerRowId);
                    if (!string.IsNullOrEmpty(CheckStatus))
                    {
                        if (CheckStatus == "Allocated-Mgr")
                        {
                            data = data.Where(p => p.MgrAllocatedTo == teamMemerRowId && p.TLAllocatedTo == 0);
                        }
                        if (CheckStatus == "Allocated")
                        {
                            data = data.Where(b => b.TLAllocatedTo > 0);
                        }
                        if (CheckStatus == "NonAllocated")
                        {
                            data = data.Where(b => b.TLAllocatedTo == 0);
                        }
                        if (CheckStatus == "Initiated")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "Initiated");
                        }
                        if (CheckStatus == "NonInitiated")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "WIP");
                        }
                        if (CheckStatus == "RejectionWIP")
                        {
                            data = data.Where(b => b.TMQCCheckStatus == "Rejected-QC");
                        }
                        if (CheckStatus == "ReOpen")
                        {
                            data = data.Where(b => b.PQAddress.PQPersonal.CaseStatus == "ReOpen");
                        }
                        if (CheckStatus == "Priority")
                        {
                            data = data.Where(b => b.PQAddress.PQPersonal.CaseType == "Priority");
                        }
                        if (CheckStatus == "InsuffWIP")
                        {
                            data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                        }
                        if (CheckStatus == "Insufficiency")
                        {
                            data = data.Where(b => b.TMQCCheckStatus == "Insufficent-QC");
                        }
                        if (CheckStatus == "PrecallingWIP")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "PrecallingWIP");
                        }
                        if (CheckStatus == "PostcallingWIP")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "PrecallingWIP");
                        }
                        if (CheckStatus == "QCPending")
                        {
                            data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                        }
                        if (CheckStatus == "FundApproval")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "Funds Pending");
                        }
                        if (CheckStatus == "Approvalpending")
                        {
                            data = data.Where(b => b.TMQCCheckStatus == "Allocated-TM");
                        }
                        if (CheckStatus == "Escalated")
                        {
                            data = data.Where(b => b.PQAddress.CheckStatus == "Escalated");
                        }
                        if (CheckStatus == "Closed")
                        {
                            data = data.Where(b => b.RWQCManagerBy > 0);
                        }
                        if (CheckStatus == "OutTAT")
                        {
                            DateTime todayTATDate = DateTime.Now;
                            data = data.Where(b => DbFunctions.TruncateTime(b.PQAddress.InternalOutDate) < DbFunctions.TruncateTime(todayTATDate));
                        }
                    }
                }
                if (Designation == "Team Leader-Add")
                {
                    data = data.Where(p => p.TLAllocatedTo == teamMemerRowId);
                    if (!string.IsNullOrEmpty(CheckStatus))
                    {
                        if (CheckStatus == "ReAllocation")
                        {
