        public IEnumerable<ExportVerificationAddressViewModel> GetExportAddressManager(int CheckFamilyRowId, string CheckStatusId, string department, int userid)
        {
            try
            {
                DataTable dt = new DataTable();
                ClientCustomize cc = new ClientCustomize();
                dt = cc.ExportToExcelAddressManager(CheckFamilyRowId, CheckStatusId, department, userid);

                List<ExportVerificationAddressViewModel> lmdAddress = new List<ExportVerificationAddressViewModel>();


                if (dt.Rows.Count > 0)
                {

                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {

                        ExportVerificationAddressViewModel aa = new ExportVerificationAddressViewModel();

                        //lmd.Add(new ExportVerificationAddressViewModel
                        //{
                        aa.ClientName = dr["ClientName"].ToString();
                        aa.CompanyRefNo = (dr["CompanyRefNo"]).ToString();
                        aa.Name = (dr["Name"]).ToString();
                        aa.AddressType = (dr["Type"]).ToString();
                        aa.address = (dr["address"]).ToString();
                        aa.AV_Pincode = dr["AV_Pincode"].ToString();
                        aa.Location = (dr["Location"]).ToString();
                        aa.StateName = (dr["StateName"]).ToString();
                        aa.MobileNo = (dr["MobileNo"]).ToString();
                        lmdAddress.Add(aa);


                    }

                }
                return lmdAddress.ToList();
            }
            catch (Exception)
            {
                throw;
            }
        }

