        public VerificationInfoListPagedModel GetAgingDetails(int pageNo, int pageSize, string Search = "", string department = "", string status = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", string SearchType = "", string sort="",string sortDir="")
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                DataTable dt = new DataTable();
                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                if (!string.IsNullOrEmpty(Search))
                {
                    dt = cc.getdashboardAgingDetails(department, status, Search, SearchType);
                }
                else
                {
                    dt = cc.getdashboardAgingDetails(department, status);
                }
                // ds = cc.getCasewiseSummaryDetail(ClientRowID, CaseStatus,ClientUserRowID);
                List<VerificationViewModel> lmd = new List<VerificationViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        VerificationViewModel mm = new VerificationViewModel();

                        mm.VerificationRowID = Convert.ToInt32(dr["VerificationRowID"].ToString());
                        mm.ClientRowID = Convert.ToInt16(dr["ClientRowID"]);
                        mm.ClientName = dr["ClientName"].ToString();
                        mm.PersonalRowID = Convert.ToInt32(dr["PersonalRowID"]);
                        mm.PersonalName = dr["Candidate Name"].ToString();
                        mm.CandidateCode = dr["CandidateCode"].ToString();
                        mm.InternalOutDate = Convert.ToDateTime(dr["InternalOutDate"].ToString());
                        ///////////////////////////


                        mm.CreatedDate = Convert.ToDateTime(dr["Created On"].ToString());
                        if (dr["TLAllocationDate"].ToString() != "" && dr["TLAllocationDate"].ToString() != null)
                        {
                            mm.TLAllocationDate = (dr["TLAllocationDate"].ToString());
                        }
                        if (dr["CompletionDate"].ToString() != "" && dr["CompletionDate"].ToString() != null)
                        {
                            mm.CompletionDate = (dr["CompletionDate"].ToString());
                        }

                        ///////////////////////////

                        mm.ClientRefID = Convert.ToString(dr["ClientRefID"].ToString());
                        mm.CompanyRefNo = Convert.ToString(dr["Securitas ID"].ToString());
                        mm.OutDate = Convert.ToDateTime(dr["OutDate"].ToString());
                        mm.ClientPackageRowID = Convert.ToInt16(dr["ClientPackageRowID"].ToString());
                        mm.CheckFamilyRowID = Convert.ToInt16(dr["CheckFamilyRowID"].ToString());
                        mm.SubCheckRowID = Convert.ToInt16(dr["SubCheckRowID"].ToString());
                        mm.SubCheckName = dr["SubCheckName"].ToString();
                        mm.UniqueComponentID = dr["UniqueComponentID"].ToString();
                        mm.CheckStatus = dr["CheckStatus"].ToString();
                        mm.ReWorkCheckStatus = dr["ReWorkCheckStatus"].ToString();
                        mm.AllocatedTMName = dr["AllocatedTMName"].ToString();
                        mm.AllocatedTLName = dr["AllocatedTLName"].ToString();
                        mm.Partner = dr["Partner"].ToString();
                        mm.AllocatedQCName = dr["AllocatedQCName"].ToString();
                        mm.UniversityName = dr["UniversityName"].ToString();
                        mm.collegeName = dr["CollegeName"].ToString();
                        mm.Link = dr["Link"].ToString();
                        mm.YearOfPassing = dr["YearOfPassing"].ToString();
                        mm.Coursename = dr["DegreeType"].ToString();
                        //mm.Location = dr["AV_Add"].ToString();
                        mm.SecuritasSPOC = dr["SpocName"].ToString();

                        mm.TMCompletionDate = dr["TMCompletionDate"].ToString();
                    
                        mm.DateTLAllocation = (dr["TLAllocationDate"].ToString());
                        mm.DateTMAllocation = (dr["TMAllocationDate"].ToString());
                        mm.DateInitiation = (dr["Created On"].ToString());

                        mm.checkFackEdu = getEducationFakelist(Convert.ToInt32(dr["PersonalRowID"]), Convert.ToInt16(dr["SubCheckRowID"]), Convert.ToInt16(dr["CheckFamilyRowID"]));
                        mm.TypeOfBusinesses = department == "Education" ? dr["TypeOfBusinesses"].ToString() : "";
                        lmd.Add(mm);






                    }
                    model.TotalRecords = dt.Rows.Count;
                }
                else
                {
                    model.TotalRecords = 0;
                }
                switch (sort)
                {                    
                    case "typeofbusinesses":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.TypeOfBusinesses).ToList() : lmd.OrderByDescending(x => x.TypeOfBusinesses).ToList();
                        break;                    
                }
                model.PageSize = pageSize;
                model.PQVerificationInfo = lmd.Skip((pageNo - 1) * pageSize).Take(pageSize);
                return model;

            }
            catch (Exception)
            {
                throw;
            }
        }
        public VerificationInfoListPagedModel GetEmploymentAutoAllocatedChecks(int pageNo, int pageSize, string sort, string sortDir, string Search = "", string designation = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", byte tatdays = 0, string RecievingToDate = "", string RecievingFromDate = "", string CompletedToDate = "", string CompletedFromDate = "", string DCheckStatus = "", string CaseStatus = "", string EmployerName = "", string Allocatedto = "")
        {
            VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
            List<VerificationViewModel> datas = new List<VerificationViewModel>();
            DataTable dt1 = new DataTable();
            ClientCustomize cc = new ClientCustomize();
            dt1 = cc.GetEmploymentAutoAllocatedChecks(Search);
            if (dt1.Rows.Count > 0)
            {
                for (int i = 0; i < dt1.Rows.Count; i++)
                {
                    VerificationViewModel data = new VerificationViewModel();
                    data.CompanyRefNo = dt1.Rows[i]["CompanyRefNo"].ToString();
                    data.UniqueComponentID = dt1.Rows[i]["CheckUniqueID"].ToString();
                    data.CurrentlyAllocatedTM = dt1.Rows[i]["AllocatedTo"].ToString();
                    data.DateTMAllocation = dt1.Rows[i]["TMAllocationDate"].ToString();
                    data.AutoAllocatedTM = dt1.Rows[i]["TMFirstName"].ToString();
                    data.Organization_Name = dt1.Rows[i]["OrganizationName"].ToString();


                    datas.Add(data);

                }

            }
            var pagedData = datas.Skip((pageNo - 1) * pageSize).Take(pageSize).ToList();
            model.PageSize = pageSize;
            model.TotalRecords = datas.Count();
            model.PQVerificationInfo = pagedData;
            return model;
        }

