        public VerificationInfoListPagedModel GetCandidateEducationListForTLAllocation(int pageNo, int pageSize, string sort, string sortDir, string Search = "", string department = "", string statusid = "", short teamMemerRowId = 0, short ClientRowID = 0, string CheckStatus = "", string ReAllocation = "", string universityName = "", string collegeName = "", string CourseName = "", string YrOfPassing = "", short AllocateTM = 0, short AllocateTMQC = 0
            )
        {
            try
            {
                if (pageNo < 0)
                {
                    pageNo = 1;
                }

                DataTable dt = new DataTable();
                VerificationInfoListPagedModel model = new VerificationInfoListPagedModel();
                if (!string.IsNullOrEmpty(Search))
                {
                    dt = cc.getDashboardOperationTLDetail(department, teamMemerRowId, statusid, Search);
                }
                else
                {
                    dt = cc.getDashboardOperationTLDetail(department, teamMemerRowId, statusid, "");
                }
                // ds = cc.getCasewiseSummaryDetail(ClientRowID, CaseStatus,ClientUserRowID);
                List<VerificationViewModel> lmd = new List<VerificationViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        lmd.Add(new VerificationViewModel
                        {
                            VerificationRowID = Convert.ToInt32(dr["CheckId"].ToString()),
                            ClientRowID = Convert.ToInt16(dr["ClientRowID"]),
                            ClientName = dr["ClientName"].ToString(),
                            PersonalRowID = Convert.ToInt32(dr["PersonalRowID"]),
                            PersonalName = dr["Candidate Name"].ToString(),
                            CandidateCode = dr["CandidateCode"].ToString(),
                            InternalOutDate = Convert.ToDateTime(dr["InternalOutDate"].ToString()),
                            ClientRefID = dr["ClientRefID"].ToString(),
                            CompanyRefNo = dr["Securitas ID"].ToString(),
                            OutDate = Convert.ToDateTime(dr["OutDate"].ToString()),
                            ClientPackageRowID = Convert.ToInt16(dr["ClientPackageRowID"].ToString()),
                            CheckFamilyRowID = Convert.ToInt16(dr["CheckFamilyRowID"].ToString()),
                            SubCheckRowID = Convert.ToInt16(dr["SubCheckRowID"].ToString()),
                            SubCheckName = dr["SubCheckName"].ToString(),
                            UniqueComponentID = dr["UniqueComponentID"].ToString(),
                            CheckStatus = dr["CheckStatus"].ToString(),
                            ReWorkCheckStatus = dr["ReWorkCheckStatus"].ToString(),
                            UniversityName = dr["UniversityName"].ToString(),
                            collegeName = dr["CollegeName"].ToString(),
                            YearOfPassing = dr["YearOfPassing"].ToString(),
                            Coursename = dr["DegreeType"].ToString(),
                            RollNo = dr["RollNo"].ToString(),
                            checkFackEdu = getEducationFakelist(Convert.ToInt32(dr["PersonalRowID"]), Convert.ToInt16(dr["SubCheckRowID"]), Convert.ToInt16(dr["CheckFamilyRowID"])),
                            TypeOfBusinesses= department == "Education" ? dr["TypeOfBusinesses"].ToString() : ""
                            //AllocatedTMName = dr["AllocatedTMName"].ToString(),
                            //AllocatedQCName = dr["AllocatedQCName"].ToString(),
                            //SecuritasSPOC = dr["SpocName"].ToString()
                        });

                    }
                    model.TotalRecords = dt.Rows.Count;
                }
                else
                {
                    model.TotalRecords = 0;
                }
                model.PageSize = pageSize;
                if (universityName != "")
                {
                    lmd = lmd.Where(T => T.UniversityName.ToLower().Contains(universityName.ToLower())).ToList();
                }
                if (collegeName != "")
                {
                    lmd = lmd.Where(T => T.collegeName.ToLower().Contains(collegeName.ToLower())).ToList();
                }
                if (CourseName != "")
                {
                    lmd = lmd.Where(T => T.Coursename.ToLower().Contains(CourseName.ToLower())).ToList();
                }
                if (YrOfPassing != "")
                {
                    lmd = lmd.Where(T => T.YearOfPassing.ToLower().Contains(YrOfPassing.ToLower())).ToList();
                }

                switch (sort)
                {
                    case "clientname":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.ClientName).ToList() : lmd.OrderByDescending(x => x.ClientName).ToList();
                        break;
                    case "companyrefno":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.CompanyRefNo).ToList() : lmd.OrderByDescending(x => x.CompanyRefNo).ToList();
                        break;
                    case "collegename":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.collegeName).ToList() : lmd.OrderByDescending(x => x.collegeName).ToList();
                        break;
                    case "universityname":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.UniversityName).ToList() : lmd.OrderByDescending(x => x.UniversityName).ToList();
                        break;
                    case "coursename":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.Coursename).ToList() : lmd.OrderByDescending(x => x.Coursename).ToList();
                        break;
                    case "yearofpassing":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.YearOfPassing).ToList() : lmd.OrderByDescending(x => x.YearOfPassing).ToList();
                        break;
                    case "typeofbusinesses":
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.TypeOfBusinesses).ToList() : lmd.OrderByDescending(x => x.TypeOfBusinesses).ToList();
                        break;
                    default:
                        lmd = sortDir == "asc" ? lmd.OrderBy(x => x.CompanyRefNo).ToList() : lmd.OrderByDescending(x => x.CompanyRefNo).ToList();
                        break;
                }
                model.PQVerificationInfo = lmd.Skip((pageNo - 1) * pageSize).Take(pageSize);
                return model;



                return model;
            }
            catch (Exception)
            {
                throw;
            }
        }


