        public CheckVerificationViewModel GetCheckVerificationDeatils(string CompanyRefNo)
        {
            CheckVerificationViewModel model = new CheckVerificationViewModel();
            List<CheckVerificationList> ChecksLists = new List<CheckVerificationList>();
            ClientCustomize CC = new ClientCustomize();
            DataTable DTtbl = new DataTable();
            DTtbl = CC.GetCheckVerificationDetails(CompanyRefNo);
            if (DTtbl.Rows.Count > 0)
            {
                model.CompanyRefNo = DTtbl.Rows[0]["CompanyRefNo"].ToString();
                model.PersonalRowId = Convert.ToInt32(DTtbl.Rows[0]["PersonalRowId"]);
                ChecksLists = (from DataRow dr in DTtbl.Rows
                               select new CheckVerificationList()
                               {
                                   CandCheckRowId = Convert.ToInt32(dr["CandCheckRowId"]),
                                   ClientName = Convert.ToString(dr["ClientName"]),
                                   CheckName = Convert.ToString(dr["SubCheckName"]),
                                   CompanyRefNo = Convert.ToString(dr["CompanyRefNo"]),
                                   PersonalRowId = Convert.ToInt32(dr["PersonalRowID"]),
                                   CandidateFullName = Convert.ToString(dr["CandidateFullName"]),
                                   SubCheckRowId = Convert.ToInt32(dr["SubCheckFamilyID"]),
                                   CheckStatusId = Convert.ToInt32(dr["CheckStatusID"])
                               }).ToList();
            }
            model.CheckVerificationList = ChecksLists;
            return model;
        }

