        public List<UANCheckAPIResults> UANCheckAPIResults(string CompanyRefNo = "", string UAN = "", string Datefrom = "", string DateTo = "")
        {
            List<UANCheckAPIResults> Model = new List<UANCheckAPIResults>();
            try
            {
                ClientCustomize CE = new ClientCustomize();
                DataTable tbl = new DataTable();
                tbl = CE.GetSprintVerifyepfo_without_otpDetails(CompanyRefNo, UAN, Datefrom, DateTo);
                if (tbl.Rows.Count > 0)
                {
                    Model = (from DataRow dr in tbl.Rows
                             select new UANCheckAPIResults()
                             {
                                 AutoId = Convert.ToInt32(dr["AutoId"]),
                                 CompanyRefNo = Convert.ToString(dr["CompanyRefNo"]),
                                 UANNO = Convert.ToString(dr["UANNO"]),
                                 status = Convert.ToString(dr["status"]),
                                 message = Convert.ToString(dr["message"]),
                                 reference_id = Convert.ToString(dr["reference_id"]),
                                 ReportDate = Convert.ToDateTime(dr["VerifyDate"]),

                                 name = Convert.ToString(dr["name"]),
                                 guardian_name = Convert.ToString(dr["guardian_name"]),
                                 establishment_name = Convert.ToString(dr["establishment_name"]),
                                 member_id = Convert.ToString(dr["member_id"]),
                                 date_of_joining = Convert.ToString(dr["date_of_joining"]),
                                 date_of_exit = Convert.ToString(dr["date_of_exit"])

                             }).ToList();

                }
            }
            catch (Exception ex)
            {
                var rst = ex.Message;
                throw;
            }
            return Model;
        }

