        public List<SpocActionRemark> GetSpocActionRemark(int PersonalRowID, int SubCheckRowID)
        {
            try
            {
                DataTable dt = new DataTable();
                dt = cc.GetSpocActionRemark(PersonalRowID, SubCheckRowID);
                List<SpocActionRemark> lmd = new List<SpocActionRemark>();
                if (dt.Rows.Count > 0)
                {
                    lmd = (from DataRow dr in dt.Rows
                           select new SpocActionRemark()
                           {
                               PersonalRowID = Convert.ToInt32(dr["PersonalRowID"]),
                               SubCheckRowId = Convert.ToInt16(dr["SubCheckRowId"]),
                               SpocRemark = Convert.ToString(dr["SpocRemark"]),
                               PriorityType = Convert.ToString(dr["PriorityType"]),
                           }).ToList();
                }
                return lmd;
            }
            catch (Exception ex)
            {
                throw;
            }
        }
        public string getEducationFakelist(int PersonalRowid, int SubcheckRowID, int CheckFamilyRowID)
        {
            string checkFack = "notfake";
            DataTable dt = new DataTable();
            if (CheckFamilyRowID == 11)
            {
                //dt = DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, "getEducationFakeList",
                //    DAS.CreateParameter("@PersonalRowid", SqlDbType.Int, PersonalRowid, ParameterDirection.Input, 1000, false),
                //    DAS.CreateParameter("@SubcheckRowID", SqlDbType.Int, SubcheckRowID, ParameterDirection.Input, 1000, false)
                //);
                dt = DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, "getEducationNewFakeList",
                   DAS.CreateParameter("@PersonalRowid", SqlDbType.Int, PersonalRowid, ParameterDirection.Input, 1000, false),
                   DAS.CreateParameter("@SubcheckRowID", SqlDbType.Int, SubcheckRowID, ParameterDirection.Input, 1000, false)
               );
            }
            else if (CheckFamilyRowID == 12)
            {
                dt = DAS.ExecuteDataTable(DAS.ConnectionString, CommandType.StoredProcedure, "getEmployerFakeList",
                    DAS.CreateParameter("@PersonalRowid", SqlDbType.Int, PersonalRowid, ParameterDirection.Input, 1000, false),
                    DAS.CreateParameter("@SubcheckRowID", SqlDbType.Int, SubcheckRowID, ParameterDirection.Input, 1000, false)
                );
            }
            if (dt.Rows.Count > 0)
            {
                foreach (DataRow dr in dt.Rows)
                {
                    string FakeStatus = "";
                    FakeStatus = dr["FakeStatus"].ToString();
                    if (!string.IsNullOrEmpty(FakeStatus))
                    {
                        if (FakeStatus == "Capgeminivendorsupp")
                        {
                            checkFack = "Capgeminivendorsupp";
                        }
                        else
                        {
                            checkFack = "fake";
                        }
                            
                    }
                    else
                    {
                        checkFack = "notfake";
                    }
                }
            }
            else
            {
                checkFack = "notfake";
            }
            return checkFack;
        }

