                {
                    dt = cc.getReferenceSubjectNotMatchDetail(mailstatus, CheckStatus);
                }
                else
                {
                    dt = cc.getReferenceSubjectNotMatchDetail(mailstatus, CheckStatus);
                }

                List<AutoRevertViewModel> lmd = new List<AutoRevertViewModel>();
                if (dt.Rows.Count > 0)
                {
                    foreach (DataRow dr in dt.Rows) // loop for adding add from dataset to list<modeldata>
                    {
                        AutoRevertViewModel mm = new AutoRevertViewModel();

                        mm.id = Convert.ToInt32(dr["autoID"].ToString());

                        mm.Subject = dr["Subject"].ToString();
